import React, { useCallback, useContext, useEffect, useRef, useState } from 'react';

import { BaseImage as DefaultBaseImage } from '../BaseImage';
import { GalleryHeader } from './GalleryHeader';
import { useGalleryContext } from './GalleryContext';
import { Button, type ButtonProps } from '../Button';
import {
  ModalContext,
  useComponentContext,
  useComponentContextIcons,
  useTranslationContext,
} from '../../context';
import { VideoPlayer } from '../VideoPlayer';
import { VideoThumbnail } from '../VideoPlayer/VideoThumbnail';

import clsx from 'clsx';

const SWIPE_THRESHOLD = 50;
const TRANSITION_DURATION = 300;

export const GalleryUI = () => {
  const { IconChevronLeft, IconChevronRight } = useComponentContextIcons();
  const { BaseImage = DefaultBaseImage } = useComponentContext();
  const { t } = useTranslationContext();
  const {
    closeOnBackgroundClick,
    currentIndex,
    currentItem,
    goToNext,
    goToPrevious,
    hasNext,
    hasPrevious,
    itemCount,
    onRequestClose,
  } = useGalleryContext();
  const modalContext = useContext(ModalContext);

  // Index of the item whose thumbnail play button was clicked. Comparing it with `currentIndex`
  // keeps the next item from rendering with the previous item's playback state.
  const [playRequestedIndex, setPlayRequestedIndex] = useState<number | null>(null);
  const playVideo = playRequestedIndex === currentIndex;
  const hasVideoThumbnail = Boolean(currentItem.videoThumbnailUrl);

  const isTransitioningRef = useRef(false);
  const [slideOffset, setSlideOffset] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [slideDirection, setSlideDirection] = useState<'forward' | 'backward' | null>(
    null,
  );

  // A swipe or drag can be followed by a click; skip that one so it does not close the gallery.
  const ignoreNextClickRef = useRef(false);
  const touchStartRef = useRef<{ x: number; y: number } | null>(null);
  const isVerticalSwipeRef = useRef(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setPlayRequestedIndex(null);
  }, [currentIndex]);

  const prevIndexRef = useRef(currentIndex);
  useEffect(() => {
    if (prevIndexRef.current === currentIndex) return;
    const direction = currentIndex > prevIndexRef.current ? 'forward' : 'backward';
    setSlideDirection(direction);
    setSlideOffset(0);
    setIsDragging(false);
    isTransitioningRef.current = true;

    const timer = setTimeout(() => {
      setSlideDirection(null);
      isTransitioningRef.current = false;
    }, TRANSITION_DURATION);

    prevIndexRef.current = currentIndex;
    return () => clearTimeout(timer);
  }, [currentIndex]);

  // Navigation is ignored while a slide transition is running.
  const handleGoToNext = useCallback(() => {
    if (isTransitioningRef.current) return;
    goToNext();
  }, [goToNext]);

  const handleGoToPrevious = useCallback(() => {
    if (isTransitioningRef.current) return;
    goToPrevious();
  }, [goToPrevious]);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (event.key === 'ArrowLeft') {
        event.preventDefault();
        handleGoToPrevious();
      } else if (event.key === 'ArrowRight') {
        event.preventDefault();
        handleGoToNext();
      }
    },
    [handleGoToNext, handleGoToPrevious],
  );

  useEffect(() => {
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const handleTouchStart = useCallback((event: React.TouchEvent) => {
    if (isTransitioningRef.current) return;
    const touch = event.touches[0];
    ignoreNextClickRef.current = false;
    touchStartRef.current = { x: touch.clientX, y: touch.clientY };
    isVerticalSwipeRef.current = false;
  }, []);

  const handleTouchMove = useCallback(
    (event: React.TouchEvent) => {
      if (!touchStartRef.current || isTransitioningRef.current) return;

      const touch = event.touches[0];
      const deltaX = touch.clientX - touchStartRef.current.x;
      const deltaY = touch.clientY - touchStartRef.current.y;

      // The first movement past 10px decides between a vertical swipe (ignored) and a drag.
      if (!isDragging && !isVerticalSwipeRef.current) {
        if (Math.abs(deltaY) > Math.abs(deltaX) && Math.abs(deltaY) > 10) {
          ignoreNextClickRef.current = true;
          isVerticalSwipeRef.current = true;
          return;
        }
        if (Math.abs(deltaX) > 10) {
          ignoreNextClickRef.current = true;
          setIsDragging(true);
        }
      }

      if (isVerticalSwipeRef.current) return;

      // Dragging past the first or last item is damped to 30% (rubber band).
      if ((!hasNext && deltaX < 0) || (!hasPrevious && deltaX > 0)) {
        setSlideOffset(deltaX * 0.3);
      } else {
        setSlideOffset(deltaX);
      }
    },
    [isDragging, hasNext, hasPrevious],
  );

  const handleTouchEnd = useCallback(() => {
    if (!touchStartRef.current || isVerticalSwipeRef.current) {
      if (isVerticalSwipeRef.current) ignoreNextClickRef.current = true;
      touchStartRef.current = null;
      return;
    }

    const offset = slideOffset;
    if (isDragging || Math.abs(offset) > 10) {
      ignoreNextClickRef.current = true;
    }
    touchStartRef.current = null;

    if (Math.abs(offset) >= SWIPE_THRESHOLD) {
      if (offset < 0 && hasNext) {
        goToNext();
      } else if (offset > 0 && hasPrevious) {
        goToPrevious();
      } else {
        // Snap back: there is no item in that direction.
        setSlideOffset(0);
      }
    } else {
      // Snap back: the swipe is below the threshold.
      setSlideOffset(0);
    }

    setIsDragging(false);
  }, [slideOffset, hasNext, hasPrevious, goToNext, goToPrevious, isDragging]);

  const requestClose = modalContext?.close ?? onRequestClose;
  const handleBackgroundClick = useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      if (event.target !== event.currentTarget) return;

      if (ignoreNextClickRef.current) {
        ignoreNextClickRef.current = false;
        return;
      }

      if (!closeOnBackgroundClick) return;

      requestClose?.();
    },
    [closeOnBackgroundClick, requestClose],
  );

  const mediaStyle: React.CSSProperties =
    isDragging || (slideOffset !== 0 && slideDirection === null)
      ? { transform: `translateX(${slideOffset}px)` }
      : {};

  return (
    <div className='str-chat__gallery'>
      <div className='str-chat__gallery__main'>
        <GalleryHeader currentItem={currentItem} />
        <NavButton
          aria-label={t('gallery.ui.previousImage.ariaLabel', 'Previous image')}
          className={clsx(
            'str-chat__gallery__nav-button--prev',
            !hasPrevious && 'str-chat__gallery__nav-button--hidden',
          )}
          disabled={!hasPrevious}
          onClick={handleGoToPrevious}
        >
          <IconChevronLeft />
        </NavButton>
        <div
          className='str-chat__gallery__slide-container'
          onClick={handleBackgroundClick}
          onTouchEnd={handleTouchEnd}
          onTouchMove={handleTouchMove}
          onTouchStart={handleTouchStart}
          ref={containerRef}
        >
          <div
            className={clsx('str-chat__gallery__media-container', {
              'str-chat__gallery__media--dragging': isDragging,
              'str-chat__gallery__media--slide-backward':
                !isDragging && slideDirection === 'backward',
              'str-chat__gallery__media--slide-forward':
                !isDragging && slideDirection === 'forward',
            })}
            style={mediaStyle}
          >
            {currentItem.videoUrl ? (
              <div className='str-chat__gallery__media str-chat__gallery__media--video'>
                {/* Without a thumbnail to click, the player shows right away and waits for play. */}
                {playVideo || !hasVideoThumbnail ? (
                  <VideoPlayer isPlaying={playVideo} videoUrl={currentItem.videoUrl} />
                ) : (
                  <VideoThumbnail
                    alt={currentItem.title ?? ''}
                    onPlay={() => setPlayRequestedIndex(currentIndex)}
                    src={currentItem.videoThumbnailUrl}
                  />
                )}
              </div>
            ) : (
              <div className='str-chat__gallery__media str-chat__gallery__media--image'>
                <BaseImage alt={currentItem.alt} src={currentItem.imageUrl} />
              </div>
            )}
          </div>
        </div>
        <NavButton
          aria-label={t('gallery.ui.nextImage.ariaLabel', 'Next image')}
          className={clsx(
            'str-chat__gallery__nav-button--next',
            !hasNext && 'str-chat__gallery__nav-button--hidden',
          )}
          disabled={!hasNext}
          onClick={handleGoToNext}
        >
          <IconChevronRight />
        </NavButton>
      </div>
      {itemCount > 1 && (
        <div className='str-chat__gallery__position-indicator'>
          {currentIndex + 1} of {itemCount}
        </div>
      )}
    </div>
  );
};

const NavButton = ({ className, ...props }: ButtonProps) => (
  <Button {...props} className={clsx('str-chat__gallery__nav-button', className)} />
);
